def client_name(profile_path):
	A=profile_path
	if not A:return''
	try:
		with open(A,encoding='utf-8-sig')as C:B=json.load(C)
	except(OSError,ValueError):return''
	return str(B.get('organization_name')or B.get('organization_name_en')or'')[:80]
def build_data(skill,lang,profile=None):C=skill;A=lang;D=S[C][A];B={'skill':C,'lang':A,'job':S[C]['job'][A],'client':client_name(profile),'texts':COMMON[A]};B.update(D);E=[A for A in(B.get('shot')or{},)if A.get('src')];B['shots']={A['src']:SHOTS[A['src']]for A in E if A['src']in SHOTS};return B
def render(data):
	with open(TEMPLATE,encoding='utf-8')as B:A=B.read()
	if A.count('__INTAKE__')!=1:raise ValueError('התבנית חייבת להכיל את __INTAKE__ פעם אחת בדיוק')
	C=json.dumps(data,ensure_ascii=False).replace('</','<\\/').replace('\u2028','\\u2028').replace('\u2029','\\u2029');return A.replace('__INTAKE__',C)
def main(argv=None):
	cli.utf8_stdio();B=cli.parser('בונה את חצי המסך של שלב התשאול לסקיל של Areo');B.add_argument('--skill',required=True,choices=SKILLS);B.add_argument('--lang',required=True,choices=('he','en'));B.add_argument('--profile',default=None,help='פרופיל-לקוח.json (אופציונלי, לשם הארגון בראש העמוד)');A=B.parse_args(argv);C=cli.guard_out(A.out,inputs=[A.profile]if A.profile else[]);D=build_data(A.skill,A.lang,A.profile);E=render(D);os.makedirs(os.path.dirname(C)or'.',exist_ok=True)
	with open(C,'w',encoding='utf-8',newline='\n')as F:F.write(E)
	print(json.dumps({'out':C,'skill':A.skill,'lang':A.lang,'capabilities':CAPABILITIES},ensure_ascii=False));return 0
if __name__=='__main__':sys.exit(cli.run(main))
